/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { CNF, EncodedCNF, Literal, Matrix, Q, Rational, add, mul, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.logic.algorithms.lra_theory", () => {
  it("enc.add_from_cnf(cnf)", () => {
    const [y, x] = symbols('y x');
    const v1 = new EncodedCNF([[1, 2], [3, 4], [5, 6]], [[Q.lt(y, Rational.of(1n, 1n, { gcd: 1n })), 1], [Q.gt(y, Rational.of(1n, 1n, { gcd: 1n })), 2], [Q.eq(x, Rational.of(0n, 1n, { gcd: 1n })), 3], [Q.eq(y, Rational.of(1n, 1n, { gcd: 1n })), 4], [Q.lt(x, Rational.of(0n, 1n, { gcd: 1n })), 5], [Q.gt(x, Rational.of(0n, 1n, { gcd: 1n })), 6]]);
    const v2 = x;
    const v3 = Rational.of(0n, 1n, { gcd: 1n });
    const v4 = Q.eq(v2, v3);
    const v5 = new Literal(v4, false);
    const v6 = y;
    const v7 = Rational.of(1n, 1n, { gcd: 1n });
    const v8 = Q.eq(v6, v7);
    const v9 = new Literal(v8, false);
    const v10 = x;
    const v11 = Rational.of(0n, 1n, { gcd: 1n });
    const v12 = Q.gt(v10, v11);
    const v13 = new Literal(v12, false);
    const v14 = x;
    const v15 = Rational.of(0n, 1n, { gcd: 1n });
    const v16 = Q.lt(v14, v15);
    const v17 = new Literal(v16, false);
    const v18 = y;
    const v19 = Rational.of(1n, 1n, { gcd: 1n });
    const v20 = Q.gt(v18, v19);
    const v21 = new Literal(v20, false);
    const v22 = y;
    const v23 = Rational.of(1n, 1n, { gcd: 1n });
    const v24 = Q.lt(v22, v23);
    const v25 = new Literal(v24, false);
    const v26 = new CNF([[v5, v9], [v13, v17], [v21, v25]]);
    v1.addFromCnf(v26);
    expect(sympyStr(v1.addFromCnf(v26))).toBe('None');
  });
  it("Matrix(3, 3, var('a:i'))", () => {
    const [a, b, c, d, e, f, g, h, i] = symbols('a b c d e f g h i');
    expect(sympyStr(Matrix.row(a, b, c, d, e, f, g, h, i).reshape(3, 3))).toBe('Matrix([[a, b, c], [d, e, f], [g, h, i]])');
  });
  it("enc.from_cnf(cnf)", () => {
    const [x, z, y] = symbols('x z y');
    const v1 = new EncodedCNF([[1, 6], [2, 5], [3], [4]], [[Q.gt(add(x, mul(Rational.of(-1n, 1n, { gcd: 1n }), z), mul(Rational.of(2n, 1n, { gcd: 1n }), y)), Rational.of(4n, 1n, { gcd: 1n })), 1], [Q.ge(add(x, mul(Rational.of(-1n, 1n, { gcd: 1n }), z), mul(Rational.of(2n, 1n, { gcd: 1n }), y)), Rational.of(6n, 1n, { gcd: 1n })), 2], [Q.ge(x, Rational.of(0n, 1n, { gcd: 1n })), 3], [Q.gt(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })), 4], [Q.le(add(x, y), Rational.of(2n, 1n, { gcd: 1n })), 5], [Q.eq(add(x, y), Rational.of(2n, 1n, { gcd: 1n })), 6]]);
    const v2 = add(x, y);
    const v3 = Rational.of(2n, 1n, { gcd: 1n });
    const v4 = Q.eq(v2, v3);
    const v5 = new Literal(v4, false);
    const v6 = Rational.of(-1n, 1n, { gcd: 1n });
    const v7 = mul(v6, z);
    const v8 = Rational.of(2n, 1n, { gcd: 1n });
    const v9 = mul(v8, y);
    const v10 = add(x, v7, v9);
    const v11 = Rational.of(4n, 1n, { gcd: 1n });
    const v12 = Q.gt(v10, v11);
    const v13 = new Literal(v12, false);
    const v14 = Rational.of(-1n, 1n, { gcd: 1n });
    const v15 = mul(v14, z);
    const v16 = Rational.of(2n, 1n, { gcd: 1n });
    const v17 = mul(v16, y);
    const v18 = add(x, v15, v17);
    const v19 = Rational.of(6n, 1n, { gcd: 1n });
    const v20 = Q.ge(v18, v19);
    const v21 = new Literal(v20, false);
    const v22 = add(x, y);
    const v23 = Rational.of(2n, 1n, { gcd: 1n });
    const v24 = Q.le(v22, v23);
    const v25 = new Literal(v24, false);
    const v26 = x;
    const v27 = Rational.of(0n, 1n, { gcd: 1n });
    const v28 = Q.ge(v26, v27);
    const v29 = new Literal(v28, false);
    const v30 = Rational.of(2n, 1n, { gcd: 1n });
    const v31 = Rational.of(1n, 1n, { gcd: 1n });
    const v32 = Q.gt(v30, v31);
    const v33 = new Literal(v32, false);
    const v34 = new CNF([[v5, v13], [v21, v25], [v29], [v33]]);
    v1.fromCnf(v34);
    expect(sympyStr(v1.fromCnf(v34))).toBe('None');
  });
});
